      <textarea [(ngModel)]="content" placeholder="Enter your text here"></textarea>
      <button (click)="save()">Save</button>
    </div>
  `,
  styleUrls: ['./editor.component.css']
})
export class EditorComponent {
  content = '';

  save() {
    console.log('Content saved:', this.content);
  }
}
```

### Step 2: Implement Comment Support

Next, add functionality for adding comments below each line of text.

```typescript
// comment-item.component.ts
import { Component } from '@angular/core';
import { ContentService } from './content.service'; // Assuming you have a service for managing content

@Component({
  selector: 'app-comment-item',
  templateUrl: './comment-item.component.html',
  styleUrls: ['./comment-item.component.css']
})
export class CommentItemComponent {
  constructor(private contentService: ContentService) {}

  getComment(index: number): string | undefined {
    return this.contentService.getComments()[index];
  }

  onAddComment(index: number) {
    const newComment = prompt("Enter your comment:");
    if (newComment) {
      this.contentService.addComment(newComment, index);
    }
  }
}
```

### Step 3: Manage Comments

Create a service to manage the comments.

```typescript
// content.service.ts
import { Injectable } from '@angular/core';

@Injectable({
  providedIn: 'root'
})
export class ContentService {
  private comments: string[] = [];

  addComment(comment: string, index: number) {
    this.comments.splice(index + 1, 0, comment); // Add at the specified index
  }

  getComments(): string[] {
    return [...this.comments]; // Return a copy to avoid mutation
  }
}
```

### Step 4: Update Template

Update the template to include the comment input field next to each piece of text.

```html
<!-- comment-item.component.html -->
<div *ngFor="let item of comments; let i = index">
  {{ item }}
  <input type="text" [(ngModel)]="comments[i]" placeholder="Add comment...">
  <button (click)="onAddComment(i)">Add</button>
</div>
```

### Step 5: Finalize the Application

Ensure that all components are correctly linked together and that data flows properly between them.

### Step 6: Run the Application

Finally, run the application using Angular CLI or any other build system you prefer.

```bash
ng serve
```

