```go
package main

import (
	"bufio"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"log"
	"os"
	"path/filepath"
)

func main() {
	if len(os.Args) < 3 {
		fmt.Println("Usage: go run script.go <source_file> <struct_name>")
		return
	}

	sourceFile := os.Args[1]
	structName := os.Args[2]

	filePath := filepath.Join(filepath.Dir(sourceFile), sourceFile)
	f, err := os.Open(filePath)
	if err != nil {
		log.Fatalf("Failed to open %s: %v", filePath, err)
	}
	defer f.Close()

	var tree *token.File
	if err = parser.ParseSource(f, &tree); err != nil {
		log.Fatalf("Failed to parse %s: %v", filePath, err)
	}

	for _, decl := range tree.Decls {
		if defn, ok := decl.(*ast.GenDecl); ok && defn.Tok == token.TYPE {
			for i := range defn.Specs {
				spec, ok := defn.Specs[i].(*ast.TypeSpec)
				if !ok || spec.Name.Name != structName {
					continue
				}

				typeDef := spec.Type

				// Extract fields (assuming fields are declared as 'field name type')
				fields := make([]string, 0)
				for fieldSpec, _ := range typeDef.Fields.List {
					fieldName := fieldSpec.Names[0].String()
					fieldType := fieldSpec.Type.String()
					fields = append(fields, fmt.Sprintf("%s:%s", fieldName, fieldType))
				}

				schema := fmt.Sprintf(`{"name": "%s", "type": "record", "fields": [`, structName)
				if len(fields) > 0 {
					schema += ``
					for i, field := range fields {
						if i > 0 {
							schema += `, `
						}
						schema += field
					}
					schema += "]}"
				} else {
					schema += `}`
				}

				fmt.Println(schema)
			}
		}
	}
}
```

